import{_ as l,o as a,c as e,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2023-04-26","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2023-04-26","date":"2023-04-26T00:00:00.000Z","updated":"2023-05-04T00:00:00.000Z","tags":["Ceph","RGW","分布式存储","删除竞赛问题","解决方案讨论"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-04-26.md","filePath":"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-04-26.md","lastUpdated":1780460162000}'),o={name:"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-04-26.md"};function r(n,i,s,h,d,p){return a(),e("div",null,[...i[0]||(i[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-多站点删除竞赛问题讨论" tabindex="-1">会议主题：多站点删除竞赛问题讨论 <a class="header-anchor" href="#会议主题-多站点删除竞赛问题讨论" aria-label="Permalink to &quot;会议主题：多站点删除竞赛问题讨论&quot;">​</a></h4><h4 id="会议时间-具体时间" tabindex="-1">会议时间：[具体时间] <a class="header-anchor" href="#会议时间-具体时间" aria-label="Permalink to &quot;会议时间：[具体时间]&quot;">​</a></h4><h4 id="参会人员-具体人员名单" tabindex="-1">参会人员：[具体人员名单] <a class="header-anchor" href="#参会人员-具体人员名单" aria-label="Permalink to &quot;参会人员：[具体人员名单]&quot;">​</a></h4><h4 id="会议内容" tabindex="-1">会议内容： <a class="header-anchor" href="#会议内容" aria-label="Permalink to &quot;会议内容：&quot;">​</a></h4><ol><li><p><strong>问题描述</strong>：</p><ul><li>讨论了多站点环境中的删除竞赛问题，即删除对象后又被重新创建，导致对象在删除后仍然存在。</li><li>该问题主要涉及桶完全同步时本地 Tombstone 缓存的可靠性问题。</li></ul></li><li><p><strong>问题根源</strong>：</p><ul><li>桶完全同步时，本地 Tombstone 缓存不足以防止对象被重新创建。</li><li>已有开发者在进行概念验证，但目前未在会议中讨论。</li></ul></li><li><p><strong>解决方案讨论</strong>：</p><ul><li>提出了两种解决方案，但都涉及无限期记住所有对象的需求。</li><li>Yehuda 建议在特定时间窗口内记住对象，以避免删除竞赛。</li><li>讨论了全同步路径中缺乏跟踪信息的问题，建议在桶列表 API 中包含跟踪信息以解决问题。</li></ul></li><li><p><strong>后续行动计划</strong>：</p><ul><li>需要进一步探索解决方案，避免无限期记住所有对象。</li><li>建议在追踪器中编写设计提案，并安排相关人员跟进。</li><li>相关 PR 需要重新测试并分享结果。</li></ul></li><li><p><strong>其他议题</strong>：</p><ul><li>讨论了 cephalicon 会议中的公平性问题，计划在当前问题解决后继续处理。</li><li>讨论了数据日志修复的测试结果，发现某些 RGW 实例的锁未释放问题。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>编写设计提案并跟进解决方案。</li><li>重新测试相关 PR 并分享结果。</li><li>继续处理数据日志修复问题。</li></ul><h4 id="后续行动" tabindex="-1">后续行动： <a class="header-anchor" href="#后续行动" aria-label="Permalink to &quot;后续行动：&quot;">​</a></h4><ul><li>编写设计提案并跟进解决方案。</li><li>重新测试相关 PR 并分享结果。</li><li>处理数据日志修复问题。</li></ul><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><p>感谢所有参与者的贡献，期待下次会议继续讨论。</p><p>会议纪要准确反映了原始内容的要点，涵盖了会议的关键细节、讨论的主要议题、决定的事项以及后续的行动计划。以下是对原始字幕内容的改进：</p><ol><li>增加了会议主题、时间、参会人员等关键信息。</li><li>在问题描述中，更明确地说明了问题的具体表现和涉及的组件。</li><li>在问题根源中，指出了本地 Tombstone 缓存的问题。</li><li>在解决方案讨论中，更详细地描述了讨论的内容和建议。</li><li>在后续行动计划中，明确了需要采取的具体行动。</li><li>在其他议题中，补充了讨论的公平性和数据日志修复问题。</li></ol><p>改进后的总结保留了计算机科学/ceph相关领域的英文原文关键词，如 Ceph、RGW、distributed storage、CRUSH algorithm、high availability、scalability、object storage 等。</p>',15)])])}const _=l(o,[["render",r]]);export{u as __pageData,_ as default};
